SET local check_function_bodies = off;

DROP POLICY "activity_entries_read" ON "better_supabase"."activity_entries";

DROP POLICY "attachments_insert" ON "better_supabase"."attachments";

CREATE TABLE "better_supabase"."donation_funds" (
  "id"          uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"   uuid                     NOT NULL,
  "key"         text                     NOT NULL,
  "name"        text                     NOT NULL,
  "kind"        text                     NOT NULL DEFAULT 'fund'::text,
  "goal"        bigint,
  "currency"    character(3),
  "starts_on"   date,
  "ends_on"     date,
  "archived_at" timestamp with time zone,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "donation_funds_check1" CHECK (((ends_on IS NULL) OR (starts_on IS NULL) OR (ends_on >= starts_on))),
  CONSTRAINT "donation_funds_check" CHECK (((goal IS NULL) OR (currency IS NOT NULL))),
  CONSTRAINT "donation_funds_currency_check" CHECK (((currency IS NULL) OR (currency ~ '^[A-Z]{3}$'::text))),
  CONSTRAINT "donation_funds_goal_check" CHECK (((goal IS NULL) OR (goal > 0))),
  CONSTRAINT "donation_funds_key_check" CHECK ((key ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
  CONSTRAINT "donation_funds_kind_check" CHECK ((kind = ANY (ARRAY['fund'::text, 'campaign'::text]))),
  CONSTRAINT "donation_funds_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 200))),
  CONSTRAINT "donation_funds_pkey" PRIMARY KEY (id),
  CONSTRAINT "donation_funds_tenant_id_id_key" UNIQUE (tenant_id, id),
  CONSTRAINT "donation_funds_tenant_id_key_key" UNIQUE (tenant_id, key)
);

ALTER TABLE "better_supabase"."donation_funds"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."donation_receipts" (
  "id"          uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"   uuid                     NOT NULL,
  "donor_type"  text                     NOT NULL,
  "donor_id"    text                     NOT NULL,
  "sequence"    bigint                   NOT NULL,
  "number"      text                     NOT NULL,
  "kind"        text                     NOT NULL,
  "year"        integer                  NOT NULL,
  "amount"      bigint                   NOT NULL,
  "currency"    character(3)             NOT NULL,
  "issued_at"   timestamp with time zone NOT NULL DEFAULT now(),
  "voided_at"   timestamp with time zone,
  "void_reason" text,
  CONSTRAINT "donation_receipts_amount_check" CHECK ((amount > 0)),
  CONSTRAINT "donation_receipts_kind_check" CHECK ((kind = ANY (ARRAY['gift'::text, 'yearly'::text]))),
  CONSTRAINT "donation_receipts_pkey" PRIMARY KEY (id),
  CONSTRAINT "donation_receipts_tenant_id_number_key" UNIQUE (tenant_id, number),
  CONSTRAINT "donation_receipts_void_reason_check" CHECK (((void_reason IS NULL) OR (length(void_reason) <= 2000)))
);

ALTER TABLE "better_supabase"."donation_receipts"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."donations" (
  "id"                    uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"             uuid                     NOT NULL,
  "donor_type"            text                     NOT NULL,
  "donor_id"              text                     NOT NULL,
  "fund_id"               uuid,
  "pledge_id"             uuid,
  "period_start"          date,
  "amount"                bigint                   NOT NULL,
  "currency"              character(3)             NOT NULL,
  "received_on"           date                     NOT NULL DEFAULT CURRENT_DATE,
  "method"                text,
  "status"                text                     NOT NULL DEFAULT 'pending'::text,
  "provider"              text,
  "payment_reference"     text,
  "transaction_id"        uuid,
  "refund_transaction_id" uuid,
  "receipt_id"            uuid,
  "note"                  text,
  "created_by"            uuid,
  "created_at"            timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"            timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "donations_amount_check" CHECK ((amount > 0)),
  CONSTRAINT "donations_currency_check" CHECK ((currency ~ '^[A-Z]{3}$'::text)),
  CONSTRAINT "donations_method_check" CHECK (((method IS NULL) OR (length(method) <= 40))),
  CONSTRAINT "donations_note_check" CHECK (((note IS NULL) OR (length(note) <= 2000))),
  CONSTRAINT "donations_pkey" PRIMARY KEY (id),
  CONSTRAINT "donations_pledge_id_period_start_key" UNIQUE (pledge_id, period_start),
  CONSTRAINT "donations_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'posted'::text, 'failed'::text, 'refunded'::text])))
);

ALTER TABLE "better_supabase"."donations"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."expense_categories" (
  "id"           uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"    uuid                     NOT NULL,
  "key"          text                     NOT NULL,
  "name"         text                     NOT NULL,
  "currency"     character(3),
  "limit_amount" bigint,
  "receipt_over" bigint,
  "archived_at"  timestamp with time zone,
  "created_at"   timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"   timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "expense_categories_check" CHECK ((((limit_amount IS NULL) AND (receipt_over IS NULL)) OR (currency IS NOT NULL))),
  CONSTRAINT "expense_categories_currency_check" CHECK (((currency IS NULL) OR (currency ~ '^[A-Z]{3}$'::text))),
  CONSTRAINT "expense_categories_key_check" CHECK ((key ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
  CONSTRAINT "expense_categories_limit_amount_check" CHECK (((limit_amount IS NULL) OR (limit_amount > 0))),
  CONSTRAINT "expense_categories_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 200))),
  CONSTRAINT "expense_categories_pkey" PRIMARY KEY (id),
  CONSTRAINT "expense_categories_receipt_over_check" CHECK (((receipt_over IS NULL) OR (receipt_over >= 0))),
  CONSTRAINT "expense_categories_tenant_id_id_key" UNIQUE (tenant_id, id),
  CONSTRAINT "expense_categories_tenant_id_key_key" UNIQUE (tenant_id, key)
);

ALTER TABLE "better_supabase"."expense_categories"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."expense_lines" (
  "id"          uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"   uuid                     NOT NULL,
  "report_id"   uuid                     NOT NULL,
  "category_id" uuid                     NOT NULL,
  "spent_on"    date                     NOT NULL,
  "description" text                     NOT NULL,
  "merchant"    text,
  "amount"      bigint                   NOT NULL,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "expense_lines_amount_check" CHECK ((amount > 0)),
  CONSTRAINT "expense_lines_description_check" CHECK (((length(description) >= 1) AND (length(description) <= 500))),
  CONSTRAINT "expense_lines_merchant_check" CHECK (((merchant IS NULL) OR (length(merchant) <= 200))),
  CONSTRAINT "expense_lines_pkey" PRIMARY KEY (id)
);

ALTER TABLE "better_supabase"."expense_lines"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."expense_reports" (
  "id"                           uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"                    uuid                     NOT NULL,
  "user_id"                      uuid                     NOT NULL,
  "title"                        text                     NOT NULL,
  "currency"                     character(3)             NOT NULL,
  "note"                         text,
  "approval_id"                  uuid,
  "submitted_at"                 timestamp with time zone,
  "approved_at"                  timestamp with time zone,
  "approval_transaction_id"      uuid,
  "reimbursed_at"                timestamp with time zone,
  "reimbursement_transaction_id" uuid,
  "cancelled_at"                 timestamp with time zone,
  "created_at"                   timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"                   timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "expense_reports_currency_check" CHECK ((currency ~ '^[A-Z]{3}$'::text)),
  CONSTRAINT "expense_reports_note_check" CHECK (((note IS NULL) OR (length(note) <= 2000))),
  CONSTRAINT "expense_reports_pkey" PRIMARY KEY (id),
  CONSTRAINT "expense_reports_title_check" CHECK (((length(title) >= 1) AND (length(title) <= 200)))
);

ALTER TABLE "better_supabase"."expense_reports"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."lease_agreements" (
  "id"                 uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"          uuid                     NOT NULL,
  "unit_id"            uuid                     NOT NULL,
  "party_type"         text                     NOT NULL,
  "party_id"           text                     NOT NULL,
  "title"              text                     NOT NULL,
  "status"             text                     NOT NULL DEFAULT 'draft'::text,
  "starts_on"          date                     NOT NULL,
  "ends_on"            date,
  "rent"               bigint                   NOT NULL,
  "currency"           character(3)             NOT NULL,
  "frequency"          text                     NOT NULL DEFAULT 'monthly'::text,
  "deposit"            bigint                   NOT NULL DEFAULT 0,
  "deposit_hold_id"    uuid,
  "renewed_at"         timestamp with time zone,
  "terminated_on"      date,
  "termination_reason" text,
  "metadata"           jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "created_by"         uuid,
  "created_at"         timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"         timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "lease_agreements_check" CHECK (((ends_on IS NULL) OR (ends_on > starts_on))),
  CONSTRAINT "lease_agreements_currency_check" CHECK ((currency ~ '^[A-Z]{3}$'::text)),
  CONSTRAINT "lease_agreements_deposit_check" CHECK ((deposit >= 0)),
  CONSTRAINT "lease_agreements_frequency_check" CHECK ((frequency = ANY (ARRAY['weekly'::text, 'monthly'::text, 'quarterly'::text, 'yearly'::text]))),
  CONSTRAINT "lease_agreements_pkey" PRIMARY KEY (id),
  CONSTRAINT "lease_agreements_rent_check" CHECK ((rent > 0)),
  CONSTRAINT "lease_agreements_status_check" CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'ended'::text, 'terminated'::text]))),
  CONSTRAINT "lease_agreements_termination_reason_check" CHECK (((termination_reason IS NULL) OR (length(termination_reason) <= 2000))),
  CONSTRAINT "lease_agreements_title_check" CHECK (((length(title) >= 1) AND (length(title) <= 200)))
);

ALTER TABLE "better_supabase"."lease_agreements"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."lease_charges" (
  "id"             uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"      uuid                     NOT NULL,
  "lease_id"       uuid                     NOT NULL,
  "period_start"   date                     NOT NULL,
  "period_end"     date                     NOT NULL,
  "amount"         bigint                   NOT NULL,
  "currency"       character(3)             NOT NULL,
  "transaction_id" uuid                     NOT NULL,
  "created_at"     timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "lease_charges_amount_check" CHECK ((amount > 0)),
  CONSTRAINT "lease_charges_check" CHECK ((period_end > period_start)),
  CONSTRAINT "lease_charges_lease_id_period_start_key" UNIQUE (lease_id, period_start),
  CONSTRAINT "lease_charges_pkey" PRIMARY KEY (id)
);

ALTER TABLE "better_supabase"."lease_charges"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."maintenance_requests" (
  "id"          uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"   uuid                     NOT NULL,
  "unit_id"     uuid                     NOT NULL,
  "lease_id"    uuid,
  "title"       text                     NOT NULL,
  "description" text,
  "priority"    text                     NOT NULL DEFAULT 'normal'::text,
  "status"      text                     NOT NULL DEFAULT 'open'::text,
  "reported_by" uuid,
  "assignee_id" uuid,
  "resolved_at" timestamp with time zone,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "maintenance_requests_description_check" CHECK (((description IS NULL) OR (length(description) <= 5000))),
  CONSTRAINT "maintenance_requests_pkey" PRIMARY KEY (id),
  CONSTRAINT "maintenance_requests_priority_check" CHECK ((priority = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text, 'urgent'::text]))),
  CONSTRAINT "maintenance_requests_status_check" CHECK ((status = ANY (ARRAY['open'::text, 'in_progress'::text, 'resolved'::text, 'cancelled'::text]))),
  CONSTRAINT "maintenance_requests_title_check" CHECK (((length(title) >= 1) AND (length(title) <= 200)))
);

ALTER TABLE "better_supabase"."maintenance_requests"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."pledges" (
  "id"                uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"         uuid                     NOT NULL,
  "donor_type"        text                     NOT NULL,
  "donor_id"          text                     NOT NULL,
  "fund_id"           uuid,
  "amount"            bigint                   NOT NULL,
  "currency"          character(3)             NOT NULL,
  "frequency"         text                     NOT NULL DEFAULT 'monthly'::text,
  "starts_on"         date                     NOT NULL,
  "ends_on"           date,
  "status"            text                     NOT NULL DEFAULT 'active'::text,
  "provider"          text,
  "provider_customer" text,
  "note"              text,
  "created_by"        uuid,
  "created_at"        timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"        timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "pledges_amount_check" CHECK ((amount > 0)),
  CONSTRAINT "pledges_check" CHECK (((ends_on IS NULL) OR (ends_on > starts_on))),
  CONSTRAINT "pledges_currency_check" CHECK ((currency ~ '^[A-Z]{3}$'::text)),
  CONSTRAINT "pledges_frequency_check" CHECK ((frequency = ANY (ARRAY['weekly'::text, 'monthly'::text, 'quarterly'::text, 'yearly'::text]))),
  CONSTRAINT "pledges_note_check" CHECK (((note IS NULL) OR (length(note) <= 2000))),
  CONSTRAINT "pledges_pkey" PRIMARY KEY (id),
  CONSTRAINT "pledges_status_check" CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text, 'ended'::text])))
);

ALTER TABLE "better_supabase"."pledges"
  ENABLE ROW LEVEL SECURITY;

