CREATE POLICY "activity_entries_read" ON "better_supabase"."activity_entries"
  FOR SELECT
  TO "authenticated"
  USING
    (((organization_id IN ( SELECT better_supabase.tenant_ids_with('activity.read'::text) AS tenant_ids_with)) AND ((subject_type IS NULL) OR (subject_id IS NULL) OR (NOT
    (subject_type = ANY
    ('{comment,company,person,deal,engagement,work_item,employee,ledger_account,product,product_variant,calendar_event,asset,asset_location,lease,maintenance_request,expense_report,expense_line,donation_fund,document,customer,drive_node,application,project,task}'::text[]))) OR better_supabase.activity_subject_readable(subject_type, subject_id))));

CREATE POLICY "attachments_insert" ON "better_supabase"."attachments"
  FOR INSERT
  TO "authenticated"
  WITH CHECK (((uploaded_by = ( SELECT auth.uid() AS uid)) AND (COALESCE(better_supabase.can('tenant'::text, organization_id,
CASE subject_type
    WHEN 'comment'::text THEN 'comments.create'::text
    WHEN 'expense_line'::text THEN 'expenses.submit'::text
    ELSE 'attachments.upload'::text
END), false) OR (((organization_id)::text, subject_type, subject_id) IN ( SELECT g.tenant,
    g.subject_type,
    g.subject_id
   FROM better_supabase.portal_subjects('upload'::text) g(tenant, subject_type, subject_id)))) AND
     better_supabase.attachment_subject_readable(subject_type, subject_id, organization_id) AND ( SELECT better_supabase.actor_may_write() AS actor_may_write)));

CREATE POLICY "donation_funds_read" ON "better_supabase"."donation_funds"
  FOR SELECT
  TO "authenticated"
  USING ((tenant_id IN ( SELECT better_supabase.tenant_ids_with('donations.read'::text) AS tenant_ids_with)));

CREATE POLICY "donation_receipts_read" ON "better_supabase"."donation_receipts"
  FOR SELECT
  TO "authenticated"
  USING ((tenant_id IN ( SELECT better_supabase.tenant_ids_with('donations.read'::text) AS tenant_ids_with)));

CREATE POLICY "donations_read" ON "better_supabase"."donations"
  FOR SELECT
  TO "authenticated"
  USING ((tenant_id IN ( SELECT better_supabase.tenant_ids_with('donations.read'::text) AS tenant_ids_with)));

CREATE POLICY "expense_categories_read" ON "better_supabase"."expense_categories"
  FOR SELECT
  TO "authenticated"
  USING ((tenant_id IN ( SELECT better_supabase.tenant_ids_with('expenses.read'::text) AS tenant_ids_with)));

CREATE POLICY "expense_lines_read" ON "better_supabase"."expense_lines"
  FOR SELECT
  TO "authenticated"
  USING (((EXISTS ( SELECT 1
   FROM better_supabase.expense_reports p
  WHERE ((p.id = expense_lines.report_id) AND (p.user_id = ( SELECT auth.uid() AS uid))))) OR
    (tenant_id IN ( SELECT better_supabase.tenant_ids_with('expenses.read'::text) AS tenant_ids_with))));

CREATE POLICY "expense_reports_read" ON "better_supabase"."expense_reports"
  FOR SELECT
  TO "authenticated"
  USING (((user_id = ( SELECT auth.uid() AS uid)) OR (tenant_id IN ( SELECT better_supabase.tenant_ids_with('expenses.read'::text) AS tenant_ids_with))));

CREATE POLICY "lease_agreements_read" ON "better_supabase"."lease_agreements"
  FOR SELECT
  TO "authenticated"
  USING ((tenant_id IN ( SELECT better_supabase.tenant_ids_with('leases.read'::text) AS tenant_ids_with)));

CREATE POLICY "lease_charges_read" ON "better_supabase"."lease_charges"
  FOR SELECT
  TO "authenticated"
  USING ((tenant_id IN ( SELECT better_supabase.tenant_ids_with('leases.read'::text) AS tenant_ids_with)));

CREATE POLICY "maintenance_requests_read" ON "better_supabase"."maintenance_requests"
  FOR SELECT
  TO "authenticated"
  USING (((reported_by = ( SELECT auth.uid() AS uid)) OR (tenant_id IN ( SELECT better_supabase.tenant_ids_with('leases.read'::text) AS tenant_ids_with))));

CREATE POLICY "pledges_read" ON "better_supabase"."pledges"
  FOR SELECT
  TO "authenticated"
  USING ((tenant_id IN ( SELECT better_supabase.tenant_ids_with('donations.read'::text) AS tenant_ids_with)));

